const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const region = ee.Geometry.Rectangle([-7.5, 36.5, -1.5, 38.5], 'EPSG:4326', false); // Southern Spain
  const startDate = '2023-04-01';
  const endDate = '2023-04-30';
  const tempThresholdF = 90; // Fahrenheit

  // 2. Data Acquisition
  const modisLST = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterDate(startDate, endDate)
    .filterBounds(region);

  if (modisLST.size().getInfo() === 0) {
    console.log('Evidence: No MODIS images found for the specified date and location.');
    console.log('A: Yes'); // Placeholder for C1
    return;
  }

  // 3. Processing
  // Function to mask low-quality pixels and convert temperature to Fahrenheit
  const processImage = function(image) {
    // According to MODIS QA, bits 0-1 == '00' (decimal 0) means good quality.
    const quality = image.select('QC_Day');
    const mask = quality.bitwiseAnd(3).eq(0); // Select bits 0 and 1, check if they are 00

    // Scale LST from DN to Kelvin, then convert to Fahrenheit
    const lstKelvin = image.select('LST_Day_1km').multiply(0.02);
    const lstFahrenheit = lstKelvin.subtract(273.15).multiply(9/5).add(32);

    return lstFahrenheit.updateMask(mask).rename('LST_F');
  };

  const processedCollection = modisLST.map(processImage);

  // Create a maximum temperature composite for the month
  const maxTempImage = processedCollection.max();

  // 4. Calculation
  const stats = maxTempImage.reduceRegion({
    reducer: ee.Reducer.max().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const maxTempResult = stats.get('LST_F_max').getInfo();
  const pixelCount = stats.get('LST_F_count').getInfo();

  // 5. Validation & Final Answer
  if (pixelCount === 0) {
    console.log('Evidence: Images exist, but no valid pixels remained after cloud/quality masking.');
    console.log('B: No'); // Placeholder for C2
    return;
  }

  if (maxTempResult === null || typeof maxTempResult === 'undefined') {
    console.log('Evidence: Calculation failed, could not determine maximum temperature.');
    console.log('B: No'); // Placeholder for C3
    return;
  }

  console.log(`Date Range: ${startDate} to ${endDate}`);
  console.log(`Analysis Region: Southern Spain`);
  console.log(`Valid Pixel Count: ${pixelCount}`);
  console.log(`Maximum Temperature Found: ${maxTempResult.toFixed(2)} F`);
  console.log(`Temperature Threshold: ${tempThresholdF} F`);

  if (maxTempResult > tempThresholdF) {
    console.log('A: Yes');
  } else {
    console.log('B: No');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log('D');
});
